import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse('{"title":"notes Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"notes","tag":"notes","title":"notes Tag","prev":null,"next":"/tags/notes/page/2/","posts":[{"title":"解压和打包安卓DAT文件","url":"/posts/2015-07-28-compression-and-decompression-dat-files/","date":"2015-7-28 19:54","tags":["notes"],"html":"<p>安卓 5.0 的卡刷包系统基本上都是在一个 dat 文件里面的。但是对于很多国内 ROM，要不就是植入了很多流氓软件，\\n要不就是有很多无用软件。我们可以通过解压 DAT 文件并进行修改然后再封装回去就完美啦～</p>\\n<h2 id=\\"首先把-dat-解压成-img-镜像\\" tabindex=\\"-1\\">首先把 DAT 解压成 IMG 镜像 <a class=\\"header-anchor\\" href=\\"#首先把-dat-解压成-img-镜像\\" aria-label=\\"Permalink to &quot;首先把 DAT 解压成 IMG 镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们要使用<a href=\\"https://github.com/xpirt/sdat2img\\" target=\\"_blank\\" rel=\\"noreferrer\\">sdat2img</a>工具把 DAT 文件转换成 IMG 镜像</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./sdat2img</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">transfer_lis</span><span style=\\"color:#24292E\\">t</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_new_fil</span><span style=\\"color:#24292E\\">e</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_ext</span><span style=\\"color:#D73A49\\">4></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">-</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">transfer_lis</span><span style=\\"color:#24292E\\">t</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> input,</span><span style=\\"color:#032F62\\"> system.transfer.list</span><span style=\\"color:#032F62\\"> from</span><span style=\\"color:#032F62\\"> rom</span><span style=\\"color:#032F62\\"> zip</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">-</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_new_fil</span><span style=\\"color:#24292E\\">e</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> input,</span><span style=\\"color:#032F62\\"> system.new.dat</span><span style=\\"color:#032F62\\"> from</span><span style=\\"color:#032F62\\"> rom</span><span style=\\"color:#032F62\\"> zip</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">-</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_ext</span><span style=\\"color:#D73A49\\">4></span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> output</span><span style=\\"color:#032F62\\"> ext4</span><span style=\\"color:#032F62\\"> raw</span><span style=\\"color:#032F62\\"> image</span><span style=\\"color:#032F62\\"> file</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>一个很简单的例子:</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./sdat2img</span><span style=\\"color:#032F62\\"> system.transfer.list</span><span style=\\"color:#032F62\\"> system.new.dat</span><span style=\\"color:#032F62\\"> system.img</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>新生成的 IMG 镜像便是我们下一步需要的.</p>\\n<h2 id=\\"挂载-img-镜像\\" tabindex=\\"-1\\">挂载 IMG 镜像 <a class=\\"header-anchor\\" href=\\"#挂载-img-镜像\\" aria-label=\\"Permalink to &quot;挂载 IMG 镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> mount</span><span style=\\"color:#005CC5\\"> -t</span><span style=\\"color:#032F62\\"> ext4</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> loop</span><span style=\\"color:#032F62\\"> system.img</span><span style=\\"color:#032F62\\"> /mnt/android</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这时候你可以在系统的 /mnt/android 目录下看到文件的具体内容然后进行修改了.</p>\\n<h2 id=\\"打包回-img-镜像\\" tabindex=\\"-1\\">打包回 IMG 镜像 <a class=\\"header-anchor\\" href=\\"#打包回-img-镜像\\" aria-label=\\"Permalink to &quot;打包回 IMG 镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>把修改好的内容打包回去需要使用<a href=\\"https://github.com/EpicAOSP/make_ext4\\" target=\\"_blank\\" rel=\\"noreferrer\\">make_ext4</a>工具</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./make_ext4fs</span><span style=\\"color:#005CC5\\"> -T</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#005CC5\\"> -S</span><span style=\\"color:#032F62\\"> file_contexts</span><span style=\\"color:#005CC5\\"> -l</span><span style=\\"color:#005CC5\\"> 1073741824</span><span style=\\"color:#005CC5\\"> -a</span><span style=\\"color:#032F62\\"> system</span><span style=\\"color:#032F62\\"> system_new.img</span><span style=\\"color:#032F62\\"> /mnt/android</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>file_contexts 文件是 ROM 本身提供的.后面的一串数字指的是打包的 IMG 文件的大小 1G</p>\\n<h2 id=\\"封装成-dat-文件\\" tabindex=\\"-1\\">封装成 DAT 文件 <a class=\\"header-anchor\\" href=\\"#封装成-dat-文件\\" aria-label=\\"Permalink to &quot;封装成 DAT 文件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>封装仍需要使用工具 使用 <a href=\\"https://mega.co.nz/#!IRAi0SKL!nof6p9JmFhGQNgnNmdEKWiEwZ9NOFUVv4q9BQZfM95w\\" target=\\"_blank\\" rel=\\"noreferrer\\">rimg2sdat</a></p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./rimg2sdat</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_im</span><span style=\\"color:#24292E\\">g</span><span style=\\"color:#D73A49\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样就打包好了新的 DAT 文件,放入刷机 ROM.刷机即可~ 以上操作最好在 Linux 环境下,Win 下不保证成功.</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"http://forum.xda-developers.com/android/software-hacking/how-to-conver-lollipop-dat-files-to-t2978952\\" target=\\"_blank\\" rel=\\"noreferrer\\">XDA</a></p>\\n"},{"title":"Windows下如何进行进程注入","url":"/posts/2015-02-28-windows-injection/","date":"2015-2-28 15:53","tags":["notes"],"html":"<p>上学期学了有关 Windows 程序底层方面的知识，学习到病毒的基本工作原理。好记性不如烂笔头，学完之余还是写点东西出来吧～\\n不过我也只是抛砖引玉，详细知识还是得自己多多钻研～</p>\\n<h2 id=\\"首先打开进程\\" tabindex=\\"-1\\">首先打开进程 <a class=\\"header-anchor\\" href=\\"#首先打开进程\\" aria-label=\\"Permalink to &quot;首先打开进程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先使用 Win 系统的<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/ms684320(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">OpenProcess</a>API 打开所要注入的进程。\\n使用参数是进程的 PID，可以使用任务管理器查看进程的 PID，打开成功之后返回程序的句柄。</p>\\n<h2 id=\\"开辟内存空间\\" tabindex=\\"-1\\">开辟内存空间 <a class=\\"header-anchor\\" href=\\"#开辟内存空间\\" aria-label=\\"Permalink to &quot;开辟内存空间&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Win 系统也提供了开辟内存空间的<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/aa366890(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">VirtualAllocEx</a>API。\\n传入的参数包括进程句柄，开辟起始地址，开辟空间的大小，分配的数据类型，分配空间的权限。例如： <code>pRemoteCode = (PBYTE) VirtualAllocEx(hProcess, 0, dwSizeOfCode, MEM_COMMIT, PAGE_EXECUTE_READWRITE);</code></p>\\n<h2 id=\\"写入恶意代码\\" tabindex=\\"-1\\">写入恶意代码 <a class=\\"header-anchor\\" href=\\"#写入恶意代码\\" aria-label=\\"Permalink to &quot;写入恶意代码&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用 Win 系统的<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/ms681674(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">WriteProcessMemory</a>API 向新开辟的内存空间写入数据。注意这里写入的是二进制数据，要考虑到各种 API 函数的寻址问题。</p>\\n<h2 id=\\"执行注入的代码\\" tabindex=\\"-1\\">执行注入的代码 <a class=\\"header-anchor\\" href=\\"#执行注入的代码\\" aria-label=\\"Permalink to &quot;执行注入的代码&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>微软照样还是提供了相关的<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/ms682437(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">CreateRemoteThread</a>API，我们注意最后一个参数是输出而不是输入。</p>\\n<h2 id=\\"获取执行的结果\\" tabindex=\\"-1\\">获取执行的结果 <a class=\\"header-anchor\\" href=\\"#获取执行的结果\\" aria-label=\\"Permalink to &quot;获取执行的结果&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果要获取执行的结果，首先我们得等待线程的执行完成，使用<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/ms687032(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">WaitForSingleObject</a>API.例： <code>WaitForSingleObject(hThread, INFINITE);</code>\\n然后再使用<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/ms683190(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">GetExitCodeThread</a>API，得到返回的结果。</p>\\n<h2 id=\\"释放开辟的空间\\" tabindex=\\"-1\\">释放开辟的空间 <a class=\\"header-anchor\\" href=\\"#释放开辟的空间\\" aria-label=\\"Permalink to &quot;释放开辟的空间&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>干了坏事得不留痕迹才行，回收自己开辟的空间，使用<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/aa366894(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">VirtualFreeEx</a>API.</p>\\n<h2 id=\\"关闭打开的进程\\" tabindex=\\"-1\\">关闭打开的进程 <a class=\\"header-anchor\\" href=\\"#关闭打开的进程\\" aria-label=\\"Permalink to &quot;关闭打开的进程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>打开的进程也得关闭，使用<a href=\\"https://msdn.microsoft.com/en-us/library/windows/desktop/ms724211(v=vs.85).aspx\\" target=\\"_blank\\" rel=\\"noreferrer\\">CloseHandle</a>API.</p>\\n<p>代码示例：</p>\\n<div class=\\"language-cpp line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">cpp</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">hProcess </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> OpenProcess</span><span style=\\"color:#24292E\\">(PROCESS_CREATE_THREAD</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    |</span><span style=\\"color:#24292E\\"> PROCESS_QUERY_INFORMATION</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    |</span><span style=\\"color:#24292E\\"> PROCESS_VM_OPERATION</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    |</span><span style=\\"color:#24292E\\"> PROCESS_VM_WRITE</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    |</span><span style=\\"color:#24292E\\"> PROCESS_VM_READ,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    FALSE, PID);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (hProcess </span><span style=\\"color:#D73A49\\">==</span><span style=\\"color:#005CC5\\"> NULL</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"failed.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> -</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"ok.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"[I]: Allocating remote memory with size of 0x</span><span style=\\"color:#005CC5\\">%08x</span><span style=\\"color:#032F62\\"> ......\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    dwSizeOfCode);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">pCodeRemote </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> (PBYTE) </span><span style=\\"color:#6F42C1\\">VirtualAllocEx</span><span style=\\"color:#24292E\\">(hProcess,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">        0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        dwSizeOfCode,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        MEM_COMMIT,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        PAGE_EXECUTE_READWRITE);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (pCodeRemote </span><span style=\\"color:#D73A49\\">==</span><span style=\\"color:#005CC5\\"> NULL</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"failed.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    CloseHandle</span><span style=\\"color:#24292E\\">(hProcess);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> -</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"ok at 0x</span><span style=\\"color:#005CC5\\">%08x</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">, pCodeRemote);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">do_link_before_inj</span><span style=\\"color:#24292E\\">(pCodeRemote);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"[I]: Writing code ......\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">WriteProcessMemory</span><span style=\\"color:#24292E\\">(hProcess,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        pCodeRemote,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        pCode,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        dwSizeOfCode,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        &#x26;</span><span style=\\"color:#24292E\\">dwNumBytesXferred) </span><span style=\\"color:#D73A49\\">==</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"failed.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    VirtualFreeEx</span><span style=\\"color:#24292E\\">(hProcess, pCodeRemote,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dwSizeOfCode, MEM_RELEASE);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    CloseHandle</span><span style=\\"color:#24292E\\">(hProcess);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> -</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"ok (</span><span style=\\"color:#005CC5\\">%d</span><span style=\\"color:#032F62\\"> bytes were written).</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">, dwNumBytesXferred);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"[I]: Creating a remote thread ......\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">hThread </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> CreateRemoteThread</span><span style=\\"color:#24292E\\">(hProcess, </span><span style=\\"color:#005CC5\\">NULL</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        (LPTHREAD_START_ROUTINE) pCodeRemote,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        pCodeRemote, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\"> , </span><span style=\\"color:#D73A49\\">&#x26;</span><span style=\\"color:#24292E\\">dwThreadId);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (hThread </span><span style=\\"color:#D73A49\\">==</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"failed.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> ( pCodeRemote </span><span style=\\"color:#D73A49\\">!=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\"> )</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        VirtualFreeEx</span><span style=\\"color:#24292E\\">(hProcess, pCodeRemote, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">, MEM_RELEASE);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> ( hThread </span><span style=\\"color:#D73A49\\">!=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\"> )</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        CloseHandle</span><span style=\\"color:#24292E\\">(hThread);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> -</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"ok.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"[I]: Waiting the remote thread ......\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">WaitForSingleObject</span><span style=\\"color:#24292E\\">(hThread, INFINITE);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">GetExitCodeThread</span><span style=\\"color:#24292E\\">(hThread, (PDWORD) </span><span style=\\"color:#D73A49\\">&#x26;</span><span style=\\"color:#24292E\\">exitcode);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">printf</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\\"exited with 0x</span><span style=\\"color:#005CC5\\">%08X\\\\n</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">, exitcode);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">VirtualFreeEx</span><span style=\\"color:#24292E\\">(hProcess, pCodeRemote, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">, MEM_RELEASE);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">CloseHandle</span><span style=\\"color:#24292E\\">(hProcess);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br><span class=\\"line-number\\">62</span><br><span class=\\"line-number\\">63</span><br><span class=\\"line-number\\">64</span><br><span class=\\"line-number\\">65</span><br></div></div>"},{"title":"使用Aria2下载百度网盘和115的资源","url":"/posts/2015-01-31-aria2-download/","date":"2015-1-31 09:41","tags":["notes"],"html":"<p>虽然我已经开发了两款专门为 Aria2 用的下载插件,但是我发现还是有同学不会用 Aria2c 这么好的东西呢~\\n于是还是写一篇文章来好好的介绍下吧~</p>\\n<h2 id=\\"安装-aria2\\" tabindex=\\"-1\\">安装 Aria2 <a class=\\"header-anchor\\" href=\\"#安装-aria2\\" aria-label=\\"Permalink to &quot;安装 Aria2&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"http://aria2.sourceforge.net/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Aria2 官网</a>,通过官网应该能找到各个系统的下载包啦~\\nLinux 用户可以直接通过包管理器进行下载安装,OSX 我就没有经验了...Win 用户直接下载对应的 ZIP 包就可以了</p>\\n<h2 id=\\"配置-aria2\\" tabindex=\\"-1\\">配置 Aria2 <a class=\\"header-anchor\\" href=\\"#配置-aria2\\" aria-label=\\"Permalink to &quot;配置 Aria2&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Aria2 有两种下载模式,一种是命令行下载模式,一种是 RPC Server 模式.前者不建议使用,后者的使用方式很方便.\\nRPC 模式就是启动之后什么也不做,等着通过 RPC 接口接受下载请求.下载完也不会退出,一直等待.\\n使用命令行加参数的方式配置 Aria2 非常不推荐,建议使用配置文件的方式,下面贴出我的配置文件.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>#用户名</span></span>\\n<span class=\\"line\\"><span>#rpc-user=user</span></span>\\n<span class=\\"line\\"><span>#密码</span></span>\\n<span class=\\"line\\"><span>#rpc-passwd=passwd</span></span>\\n<span class=\\"line\\"><span>#上面的认证方式不建议使用,建议使用下面的token方式</span></span>\\n<span class=\\"line\\"><span>#设置加密的密钥</span></span>\\n<span class=\\"line\\"><span>#rpc-secret=token</span></span>\\n<span class=\\"line\\"><span>#允许rpc</span></span>\\n<span class=\\"line\\"><span>enable-rpc=true</span></span>\\n<span class=\\"line\\"><span>#允许所有来源, web界面跨域权限需要</span></span>\\n<span class=\\"line\\"><span>rpc-allow-origin-all=true</span></span>\\n<span class=\\"line\\"><span>#允许外部访问，false的话只监听本地端口</span></span>\\n<span class=\\"line\\"><span>rpc-listen-all=true</span></span>\\n<span class=\\"line\\"><span>#RPC端口, 仅当默认端口被占用时修改</span></span>\\n<span class=\\"line\\"><span>#rpc-listen-port=6800</span></span>\\n<span class=\\"line\\"><span>#最大同时下载数(任务数), 路由建议值: 3</span></span>\\n<span class=\\"line\\"><span>max-concurrent-downloads=5</span></span>\\n<span class=\\"line\\"><span>#断点续传</span></span>\\n<span class=\\"line\\"><span>continue=true</span></span>\\n<span class=\\"line\\"><span>#同服务器连接数</span></span>\\n<span class=\\"line\\"><span>max-connection-per-server=5</span></span>\\n<span class=\\"line\\"><span>#最小文件分片大小, 下载线程数上限取决于能分出多少片, 对于小文件重要</span></span>\\n<span class=\\"line\\"><span>min-split-size=10M</span></span>\\n<span class=\\"line\\"><span>#单文件最大线程数, 路由建议值: 5</span></span>\\n<span class=\\"line\\"><span>split=10</span></span>\\n<span class=\\"line\\"><span>#下载速度限制</span></span>\\n<span class=\\"line\\"><span>max-overall-download-limit=0</span></span>\\n<span class=\\"line\\"><span>#单文件速度限制</span></span>\\n<span class=\\"line\\"><span>max-download-limit=0</span></span>\\n<span class=\\"line\\"><span>#上传速度限制</span></span>\\n<span class=\\"line\\"><span>max-overall-upload-limit=0</span></span>\\n<span class=\\"line\\"><span>#单文件速度限制</span></span>\\n<span class=\\"line\\"><span>max-upload-limit=0</span></span>\\n<span class=\\"line\\"><span>#断开速度过慢的连接</span></span>\\n<span class=\\"line\\"><span>#lowest-speed-limit=0</span></span>\\n<span class=\\"line\\"><span>#验证用，需要1.16.1之后的release版本</span></span>\\n<span class=\\"line\\"><span>#referer=*</span></span>\\n<span class=\\"line\\"><span>#文件保存路径, 默认为当前启动位置</span></span>\\n<span class=\\"line\\"><span>dir=/home/acgotaku/Downloads</span></span>\\n<span class=\\"line\\"><span>#文件缓存, 使用内置的文件缓存, 如果你不相信Linux内核文件缓存和磁盘内置缓存时使用, 需要1.16及以上版本</span></span>\\n<span class=\\"line\\"><span>#disk-cache=0</span></span>\\n<span class=\\"line\\"><span>#另一种Linux文件缓存方式, 使用前确保您使用的内核支持此选项, 需要1.15及以上版本(?)</span></span>\\n<span class=\\"line\\"><span>#enable-mmap=true</span></span>\\n<span class=\\"line\\"><span>#文件预分配, 能有效降低文件碎片, 提高磁盘性能. 缺点是预分配时间较长</span></span>\\n<span class=\\"line\\"><span>#所需时间 none &#x3C; falloc ? trunc &#x3C;&#x3C; prealloc, falloc和trunc需要文件系统和内核支持</span></span>\\n<span class=\\"line\\"><span>file-allocation=prealloc</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br></div></div><p>小白用户可以直接 copy 我的配置文件保存成 aria2.conf 进行使用.<br>\\n然后在终端里面输入 <code>aria2c --conf-path=&lt;PATH&gt;</code>\\n注意 PATH 必须是绝对路径.<br>\\n例如: <code>D:\\\\aria2\\\\aria2.conf</code> 可以使用 <code>-D</code> 参数使 Aria2 在后台运行,即使关闭终端也不会停止运行.\\nWin 下可以把这个命令行保存成 bat 文件进行运行.注意路径不需要使用引号括起来.</p>\\n<p>接下来是如何管理 Aria2 的下载任务了,推荐使用 binux 菊苣的<a href=\\"http://binux.github.io/yaaw/\\" target=\\"_blank\\" rel=\\"noreferrer\\">YAAW</a>,超级好用,下载打开即用.<br>\\n懒得下载的话可以使用<a href=\\"http://binux.github.io/yaaw/demo/\\" target=\\"_blank\\" rel=\\"noreferrer\\">在线版</a>,只需在设置里面修改下 RPC PATH 为 <code>http://localhost:6800/jsonrpc</code></p>\\n<h2 id=\\"百度网盘插件\\" tabindex=\\"-1\\">百度网盘插件 <a class=\\"header-anchor\\" href=\\"#百度网盘插件\\" aria-label=\\"Permalink to &quot;百度网盘插件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我开发的百度网盘插件已经发布到<a href=\\"http://goo.gl/bPpaAS\\" target=\\"_blank\\" rel=\\"noreferrer\\">Web Store</a>了,无法翻墙的同学可以去<a href=\\"https://github.com/acgotaku/BaiduExporter/releases\\" target=\\"_blank\\" rel=\\"noreferrer\\">Github</a>下载安装包进行安装.安装之后打开<a href=\\"http://pan.baidu.com/disk/home\\" target=\\"_blank\\" rel=\\"noreferrer\\">百度网盘</a>会发现在我的设备按钮的\\n右侧多了一个导出下载按钮,如果你使用的是默认配置的话那么选中要下载的文件之后点击<code>ARIA2 RPC</code>即可导出到 Aria2 进行下载,前提是你已经开启了 Aria2 的 RPC 模式.</p>\\n<h2 id=\\"_115-网盘插件\\" tabindex=\\"-1\\">115 网盘插件 <a class=\\"header-anchor\\" href=\\"#_115-网盘插件\\" aria-label=\\"Permalink to &quot;115 网盘插件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://chrome.google.com/webstore/detail/115exporter/ojafklbojgenkohhdgdjeaepnbjffdjf\\" target=\\"_blank\\" rel=\\"noreferrer\\">115 网盘插件</a>刚刚发布功能还不完善,可能还有未知的 BUG,我后续会进行优化和开发的.安装之后打开<a href=\\"http://115.com/?mode=wangpan\\" target=\\"_blank\\" rel=\\"noreferrer\\">115 网盘</a>,\\n会发现多了一个 <code>设置导出按钮</code> 的按钮.点击这个按钮之后会提示设置成功的,然后把鼠标移动到要下载的文件上会出现 <code>导出下载</code> 的按钮,\\n点击即可导出到 Aria2 下载.</p>\\n<p>参考: <a href=\\"http://blog.binux.me/2012/12/aria2-examples/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Aria2 下载示例</a></p>\\n<p>如果有不懂的可以在<a href=\\"https://github.com/acgotaku\\" target=\\"_blank\\" rel=\\"noreferrer\\">Github</a>和<a href=\\"https://plus.google.com/u/0/+%E9%9B%AA%E6%9C%88%E7%A7%8B%E6%B0%B4%E9%85%B1/posts\\" target=\\"_blank\\" rel=\\"noreferrer\\">Google+</a>上联系我~</p>\\n"}]},"relativePath":"tags/notes/index.md","filePath":"tags/[slug].md"}'),p={name:"tags/notes/index.md"};function e(l,r,o,t,c,i){return n(),a("div")}const y=s(p,[["render",e]]);export{d as __pageData,y as default};
